PAR_NOM: dict[str, Parametre] = {}
for _p in CATALOGUE.values():
    PAR_NOM[_p.nom] = _p
    PAR_NOM.setdefault(_p.court, _p)


def parametre(designation: int | str) -> Parametre | None:
    if isinstance(designation, int):
        return CATALOGUE.get(designation)
    return PAR_NOM.get(designation)


def nom_court(physio_id: int) -> str:
    """
    Nom de colonne d'un paramètre. Un identifiant absent du catalogue reçoit un
    nom dérivé de sa valeur : il est conservé, jamais jeté — c'est la raison
    d'être du format long.
    """
    p = CATALOGUE.get(physio_id)
    return p.court if p else f'PHYSIO_{physio_id:04X}'

